SELECT quantity_bucket, store_id, avg_quantity, unique_stores FROM (SELECT CASE WHEN quantity >= 260 THEN 'high' WHEN quantity >= 98 THEN 'mid' ELSE 'low' END quantity_bucket, store_id, AVG(quantity) avg_quantity, COUNT(DISTINCT quantity) unique_stores FROM inventory GROUP BY CASE WHEN quantity >= 260 THEN 'high' WHEN quantity >= 98 THEN 'mid' ELSE 'low' END, store_id) sub WHERE avg_quantity >= 110;
